using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;

// Installs on existing mirror faces, including scenes regenerated by the furniture builders.
[DefaultExecutionOrder(200)]
public sealed class HouseMirror : MonoBehaviour
{
    private Renderer surface;
    private Material original, material;
    private Camera reflection;
    private RenderTexture texture;
    private static bool rendering;
    private static readonly System.Collections.Generic.List<HouseMirror> mirrors = new System.Collections.Generic.List<HouseMirror>();
    private readonly Plane[] frustumPlanes = new Plane[6];
    private bool[] hidden = System.Array.Empty<bool>();
    private readonly UniversalRenderPipeline.SingleCameraRequest renderRequest = new UniversalRenderPipeline.SingleCameraRequest();

    private void OnEnable()
    {
        mirrors.Add(this);
        RenderPipelineManager.beginCameraRendering += BeforeCamera;
    }
    private void OnDisable()
    {
        mirrors.Remove(this);
        RenderPipelineManager.beginCameraRendering -= BeforeCamera;
    }

    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]
    private static void Install()
    {
        foreach (var renderer in FindObjectsByType<MeshRenderer>())
            if (renderer.name == "MirrorSurface" && renderer.GetComponent<HouseMirror>() == null)
                renderer.gameObject.AddComponent<HouseMirror>();
    }

    private void Awake()
    {
        surface = GetComponent<Renderer>();
        original = surface.sharedMaterial;
        var shader = Resources.Load<Shader>("Mirrors/HouseMirror");
        if (shader == null) { enabled = false; return; }
        material = new Material(shader);
        texture = new RenderTexture(512, 512, 24) { name = "Live house mirror" };
        texture.Create();
        material.SetTexture("_ReflectionTex", texture);
        surface.sharedMaterial = material;
        reflection = new GameObject("Mirror reflection camera", typeof(Camera)).GetComponent<Camera>();
        reflection.enabled = false;
        var data = reflection.GetUniversalAdditionalCameraData();
        data.renderShadows = false;
        data.renderPostProcessing = false;
    }

    // Render before the main camera configures its own URP lighting/camera globals.
    // Submitting from LateUpdate leaves reflection state visible to other camera work.
    private void BeforeCamera(ScriptableRenderContext context, Camera source)
    {
        if (source != Camera.main) return;
        if (rendering || source == null || reflection == null || !surface.enabled) return;
        Vector3 normal = -transform.forward;
        Vector3 point = transform.position + normal * (transform.lossyScale.z * .5f);
        GeometryUtility.CalculateFrustumPlanes(source, frustumPlanes);
        if (Vector3.Dot(normal, source.transform.position - point) <= .02f ||
            Vector3.Distance(source.transform.position, point) > 7f ||
            !GeometryUtility.TestPlanesAABB(frustumPlanes, surface.bounds)) return;

        reflection.CopyFrom(source);
        reflection.enabled = false;
        reflection.cameraType = CameraType.Reflection;
        reflection.useOcclusionCulling = false;
        reflection.targetTexture = texture;
        reflection.allowMSAA = false;
        reflection.allowHDR = false;
        reflection.rect = new Rect(0, 0, 1, 1);
        reflection.ResetProjectionMatrix();
        // Reflection about the actual front plane; no dependence on the mirror's size or yaw.
        Matrix4x4 reflect = Matrix4x4.identity;
        float d = -Vector3.Dot(normal, point);
        for (int row = 0; row < 3; row++)
        {
            for (int col = 0; col < 3; col++) reflect[row, col] -= 2 * normal[row] * normal[col];
            reflect[row, 3] = -2 * d * normal[row];
        }
        reflection.transform.position = reflect.MultiplyPoint(source.transform.position);
        reflection.transform.rotation = Quaternion.LookRotation(reflect.MultiplyVector(source.transform.forward), reflect.MultiplyVector(source.transform.up));
        reflection.worldToCameraMatrix = source.worldToCameraMatrix * reflect;
        Vector3 clipPoint = reflection.worldToCameraMatrix.MultiplyPoint(point + normal * .005f);
        Vector3 clipNormal = reflection.worldToCameraMatrix.MultiplyVector(normal).normalized;
        reflection.projectionMatrix = source.CalculateObliqueMatrix(new Vector4(clipNormal.x, clipNormal.y, clipNormal.z, -Vector3.Dot(clipPoint, clipNormal)));
        material.SetMatrix("_ReflectionVP", GL.GetGPUProjectionMatrix(reflection.projectionMatrix, true) * reflection.worldToCameraMatrix);

        var bodies = FirstPersonBody.ActiveBodies;
        bool oldInvert = GL.invertCulling;
        if (hidden.Length < mirrors.Count) hidden = new bool[mirrors.Count];
        rendering = true;
        try
        {
            for (int i = 0; i < mirrors.Count; i++)
                if (mirrors[i] != null) { hidden[i] = mirrors[i].surface.forceRenderingOff; mirrors[i].surface.forceRenderingOff = true; }
            foreach (var body in bodies) body.ShowHeadInMirror(true);
            GL.invertCulling = !oldInvert;
            renderRequest.destination = texture;
            RenderPipeline.SubmitRenderRequest(reflection, renderRequest);
        }
        finally
        {
            GL.invertCulling = oldInvert;
            foreach (var body in bodies) if (body != null) body.ShowHeadInMirror(false);
            for (int i = 0; i < mirrors.Count; i++)
                if (mirrors[i] != null) mirrors[i].surface.forceRenderingOff = hidden[i];
            rendering = false;
        }
    }

    private void OnDestroy()
    {
        if (surface != null) surface.sharedMaterial = original;
        if (reflection != null) Destroy(reflection.gameObject);
        if (texture != null) { texture.Release(); Destroy(texture); }
        if (material != null) Destroy(material);
    }
}
